<?php require_once __DIR__.'/../config/db.php';require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id_categoria']??0);$n=trim($_POST['nombre']??'');$d=trim($_POST['descripcion']??'');if($n){if($id){$s=$pdo->prepare('UPDATE categorias SET nombre=?,descripcion=? WHERE id_categoria=?');$s->execute([$n,$d,$id]);}else{$s=$pdo->prepare('INSERT INTO categorias(nombre,descripcion) VALUES(?,?)');$s->execute([$n,$d]);}header('Location: categorias.php');exit;}}if(isset($_GET['eliminar'])){$s=$pdo->prepare('DELETE FROM categorias WHERE id_categoria=?');$s->execute([(int)$_GET['eliminar']]);header('Location: categorias.php');exit;}$edit=null;if(isset($_GET['editar'])){$s=$pdo->prepare('SELECT * FROM categorias WHERE id_categoria=?');$s->execute([(int)$_GET['editar']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT * FROM categorias ORDER BY nombre')->fetchAll();$title='Categorías';require 'header.php';?><h2>Categorías</h2><div class="row g-4"><div class="col-md-5"><div class="card"><div class="card-body"><h5><?=$edit?'Editar':'Nueva'?> categoría</h5><form method="post"><input type="hidden" name="id_categoria" value="<?=e($edit['id_categoria']??'')?>"><label class="form-label">Nombre</label><input class="form-control mb-2" name="nombre" required value="<?=e($edit['nombre']??'')?>"><label class="form-label">Descripción</label><textarea class="form-control mb-3" name="descripcion"><?=e($edit['descripcion']??'')?></textarea><button class="btn btn-primary">Guardar</button></form></div></div></div><div class="col-md-7"><div class="card"><div class="card-body"><table class="table"><thead><tr><th>Nombre</th><th>Descripción</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['descripcion'])?></td><td><a href="?editar=<?=$r['id_categoria']?>">Editar</a> · <a class="text-danger" href="?eliminar=<?=$r['id_categoria']?>" onclick="return confirm('¿Eliminar categoría?')">Eliminar</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php require 'footer.php';
